+  --shadow-hover:  0 8px 40px rgba(0,0,0,.7);
+  --font-sans:     'Inter', system-ui, -apple-system, sans-serif;
+  --font-serif:    'Georgia', 'Times New Roman', serif;
+  --transition:    .18s ease;
+}
+
+html { scroll-behavior: smooth; }
+
+body {
+  font-family: var(--font-sans);
+  background: var(--bg-base);
+  color: var(--text-primary);
+  line-height: 1.6;
+  min-height: 100vh;
+}
+
+img { display: block; max-width: 100%; }
+
+a {
+  color: inherit;
+  text-decoration: none;
+}
+
+button {
+  font-family: inherit;
+  cursor: pointer;
+  border: none;
+  background: none;
+}
+
+/* ── Skip Link ────────────────────────────────────────────── */
+.skip-link {
+  position: absolute;
+  top: -999px;
+  left: 8px;
+  background: var(--accent);
+  color: #0d0d0f;
+  padding: 8px 16px;
+  border-radius: var(--radius-sm);
+  font-weight: 700;
+  z-index: 9999;
+  transition: top .15s;
+}
+.skip-link:focus { top: 8px; }
+
+/* ── Focus Ring ───────────────────────────────────────────── */
+:focus-visible {
+  outline: 2px solid var(--accent);
+  outline-offset: 3px;
+  border-radius: var(--radius-sm);
+}
+
+/* ── Layout Utility ───────────────────────────────────────── */
+.container {
+  max-width: 1280px;
+  margin: 0 auto;
+  padding: 0 24px;
+}
+
+/* ── Header / Nav ─────────────────────────────────────────── */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 100;
+  background: rgba(13,13,15,.9);
+  backdrop-filter: blur(14px);
+  border-bottom: 1px solid var(--border);
+}
+
+.nav {
+  display: flex;
+  align-items: center;
+  gap: 24px;
+  height: 64px;
+}
+
+.nav__logo {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  font-size: 1.25rem;
+  font-weight: 800;
+  letter-spacing: -.5px;
+  color: var(--text-primary);
+  flex-shrink: 0;
+}
+
+.nav__logo-icon {
+  width: 32px;
+  height: 32px;
+  background: var(--accent);
+  border-radius: var(--radius-sm);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: #0d0d0f;
+  font-weight: 900;
+  font-size: .95rem;
+}
+
+.nav__links {
+  display: flex;
+  align-items: center;
+  gap: 4px;
+  list-style: none;
+  margin-left: 8px;
+}
+
+.nav__links a {
+  padding: 6px 12px;
+  border-radius: var(--radius-sm);
+  font-size: .875rem;
+  font-weight: 500;
+  color: var(--text-secondary);
+  transition: color var(--transition), background var(--transition);
+}
+
+.nav__links a:hover,
+.nav__links a[aria-current="page"] {
+  color: var(--text-primary);
+  background: var(--bg-raised);
+}
+
+.nav__spacer { flex: 1; }
+
+.nav__search {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  background: var(--bg-raised);
+  border: 1px solid var(--border);
+  border-radius: 999px;
+  padding: 7px 16px;
+  width: 220px;
+  transition: border-color var(--transition), width var(--transition);
+}
+
+.nav__search:focus-within {
+  border-color: var(--accent);
+  width: 280px;
+}
+
+.nav__search svg { color: var(--text-muted); flex-shrink: 0; }
+
+.nav__search input {
+  background: none;
+  border: none;
+  outline: none;
+  color: var(--text-primary);
+  font-size: .875rem;
+  width: 100%;
+}
+
+.nav__search input::placeholder { color: var(--text-muted); }
+
+.nav__actions {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+}
+
+.nav__icon-btn {
+  position: relative;
+  width: 40px;
+  height: 40px;
+  border-radius: var(--radius-sm);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--text-secondary);
+  transition: color var(--transition), background var(--transition);
+}
+
+.nav__icon-btn:hover {
+  color: var(--text-primary);
+  background: var(--bg-raised);
+}
+
+.nav__badge {
+  position: absolute;
+  top: 6px;
+  right: 6px;
+  width: 16px;
+  height: 16px;
+  background: var(--accent);
+  color: #0d0d0f;
+  font-size: 10px;
+  font-weight: 700;
+  border-radius: 999px;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  line-height: 1;
+}
+
+/* ── Hero ─────────────────────────────────────────────────── */
+.hero {
+  position: relative;
+  overflow: hidden;
+  min-height: 560px;
+  display: flex;
+  align-items: center;
+  background: var(--bg-surface);
+}
+
+.hero__bg {
+  position: absolute;
+  inset: 0;
+  background:
+    radial-gradient(ellipse 60% 80% at 70% 50%, #2a1f08 0%, transparent 60%),
+    radial-gradient(ellipse 40% 60% at 20% 80%, #12122a 0%, transparent 55%),
+    var(--bg-surface);
+}
+
+.hero__grid-lines {
+  position: absolute;
+  inset: 0;
+  background-image:
+    linear-gradient(var(--border) 1px, transparent 1px),
+    linear-gradient(90deg, var(--border) 1px, transparent 1px);
+  background-size: 60px 60px;
+  opacity: .35;
+  mask-image: radial-gradient(ellipse at center, black 30%, transparent 75%);
+}
+
+.hero__container {
+  position: relative;
+  z-index: 1;
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 48px;
+  align-items: center;
+  padding: 80px 24px;
+  max-width: 1280px;
+  margin: 0 auto;
+  width: 100%;
+}
+
+.hero__eyebrow {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  background: var(--accent-muted);
+  color: var(--accent);
+  font-size: .75rem;
+  font-weight: 700;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  padding: 5px 12px;
+  border-radius: 999px;
+  margin-bottom: 20px;
+  border: 1px solid #5a4a1a;
+}
+
+.hero__eyebrow-dot {
+  width: 6px;
+  height: 6px;
+  background: var(--accent);
+  border-radius: 999px;
+  animation: pulse 2s ease-in-out infinite;
+}
+
+@keyframes pulse {
+  0%, 100% { opacity: 1; transform: scale(1); }
+  50% { opacity: .5; transform: scale(.7); }
+}
+
+.hero__title {
+  font-size: clamp(2.2rem, 4.5vw, 3.5rem);
+  font-weight: 900;
+  line-height: 1.08;
+  letter-spacing: -.03em;
+  margin-bottom: 20px;
+}
+
+.hero__title em {
+  font-style: normal;
+  color: var(--accent);
+}
+
+.hero__desc {
+  font-size: 1.05rem;
+  color: var(--text-secondary);
+  margin-bottom: 36px;
+  max-width: 440px;
+  line-height: 1.7;
+}
+
+.hero__actions {
+  display: flex;
+  align-items: center;
+  gap: 14px;
+  flex-wrap: wrap;
+}
+
+.btn {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  padding: 12px 24px;
+  border-radius: var(--radius-md);
+  font-size: .9rem;
+  font-weight: 700;
+  transition: all var(--transition);
+  white-space: nowrap;
+}
+
+.btn--primary {
+  background: var(--accent);
+  color: #0d0d0f;
+}
+
+.btn--primary:hover {
+  background: var(--accent-dim);
+  transform: translateY(-1px);
+  box-shadow: 0 6px 20px rgba(232,201,109,.25);
+}
+
+.btn--ghost {
+  background: var(--bg-raised);
+  color: var(--text-primary);
+  border: 1px solid var(--border);
+}
+
+.btn--ghost:hover {
+  background: var(--bg-overlay);
+  border-color: var(--text-muted);
+}
+
+.hero__stats {
+  display: flex;
+  gap: 32px;
+  margin-top: 40px;
+  padding-top: 32px;
+  border-top: 1px solid var(--border);
+}
+
+.hero__stat-value {
+  font-size: 1.6rem;
+  font-weight: 800;
+  letter-spacing: -.03em;
+  color: var(--text-primary);
+}
+
+.hero__stat-label {
+  font-size: .78rem;
+  color: var(--text-muted);
+  margin-top: 2px;
+}
+
+.hero__visual {
+  position: relative;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+
+.hero__card-stack {
+  position: relative;
+  width: 320px;
+  height: 380px;
+}
+
+.hero__card {
+  position: absolute;
+  background: var(--bg-raised);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  box-shadow: var(--shadow-card);
+}
+
+.hero__card--main {
+  width: 260px;
+  height: 320px;
+  top: 30px;
+  left: 30px;
+  z-index: 3;
+}
+
+.hero__card--back1 {
+  width: 240px;
+  height: 300px;
+  top: 15px;
+  left: 55px;
+  z-index: 2;
+  transform: rotate(4deg);
+  opacity: .6;
+}
+
+.hero__card--back2 {
+  width: 220px;
+  height: 280px;
+  top: 5px;
+  left: 75px;
+  z-index: 1;
+  transform: rotate(8deg);
+  opacity: .35;
+}
+
+.hero__card-img {
+  width: 100%;
+  height: 200px;
+  object-fit: cover;
+  background: linear-gradient(135deg, #2a2a35 0%, #1a1a22 100%);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 4rem;
+}
+
+.hero__card-body {
+  padding: 16px;
+}
+
+.hero__card-name {
+  font-size: .9rem;
+  font-weight: 700;
+  margin-bottom: 4px;
+}
+
+.hero__card-price {
+  font-size: 1.1rem;
+  font-weight: 800;
+  color: var(--accent);
+}
+
+.hero__float-badge {
+  position: absolute;
+  background: var(--deal-red);
+  color: #fff;
+  font-size: .78rem;
+  font-weight: 700;
+  padding: 6px 12px;
+  border-radius: 999px;
+  box-shadow: 0 4px 16px rgba(232,93,93,.4);
+}
+
+.hero__float-badge--sale { top: 20px; right: 0; }
+.hero__float-badge--new { bottom: 60px; right: 10px; background: var(--accent); color: #0d0d0f; }
+
+/* ── Section Base ─────────────────────────────────────────── */
+.section {
+  padding: 72px 0;
+}
+
+.section + .section {
+  border-top: 1px solid var(--border);
+}
+
+.section__header {
+  display: flex;
+  align-items: flex-end;
+  justify-content: space-between;
+  margin-bottom: 40px;
+  gap: 16px;
+}
+
+.section__title {
+  font-size: clamp(1.5rem, 2.5vw, 2rem);
+  font-weight: 800;
+  letter-spacing: -.03em;
+}
+
+.section__subtitle {
+  color: var(--text-muted);
+  font-size: .875rem;
+  margin-top: 4px;
+}
+
+.section__link {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  font-size: .875rem;
+  font-weight: 600;
+  color: var(--accent);
+  transition: gap var(--transition);
+  flex-shrink: 0;
+}
+
+.section__link:hover { gap: 10px; }
+
+/* ── Category Pills ───────────────────────────────────────── */
+.categories {
+  background: var(--bg-surface);
+  padding: 24px 0;
+  border-bottom: 1px solid var(--border);
+}
+
+.categories__list {
+  display: flex;
+  gap: 10px;
+  overflow-x: auto;
+  scrollbar-width: none;
+  padding-bottom: 4px;
+  list-style: none;
+}
+
+.categories__list::-webkit-scrollbar { display: none; }
+
+.category-pill {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  padding: 10px 18px;
+  background: var(--bg-raised);
+  border: 1px solid var(--border);
+  border-radius: 999px;
+  font-size: .84rem;
+  font-weight: 600;
+  color: var(--text-secondary);
+  white-space: nowrap;
+  transition: all var(--transition);
+}
+
+.category-pill:hover,
+.category-pill[aria-pressed="true"] {
+  background: var(--accent-muted);
+  border-color: var(--accent-dim);
+  color: var(--accent);
+}
+
+.category-pill__emoji {
+  font-size: 1rem;
+  line-height: 1;
+}
+
+/* ── Product Grid ─────────────────────────────────────────── */
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
+  gap: 20px;
+}
+
+/* ── Product Card ─────────────────────────────────────────── */
+.product-card {
+  background: var(--bg-surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
+}
+
+.product-card:hover {
+  transform: translateY(-3px);
+  box-shadow: var(--shadow-hover);
+  border-color: var(--bg-overlay);
+}
+
+.product-card__media {
+  position: relative;
+  aspect-ratio: 4/3;
+  background: var(--bg-raised);
+  overflow: hidden;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 3.5rem;
+}
+
+.product-card__media-bg {
+  position: absolute;
+  inset: 0;
+  transition: transform .4s ease;
+}
+
+.product-card:hover .product-card__media-bg {
+  transform: scale(1.04);
+}
+
+.product-card__badge {
+  position: absolute;
+  top: 10px;
+  left: 10px;
+  background: var(--deal-red);
+  color: #fff;
+  font-size: .7rem;
+  font-weight: 700;
+  letter-spacing: .05em;
+  text-transform: uppercase;
+  padding: 3px 8px;
+  border-radius: var(--radius-sm);
+}
+
+.product-card__badge--new {
+  background: var(--accent);
+  color: #0d0d0f;
+}
+
+.product-card__wishlist {
+  position: absolute;
+  top: 10px;
+  right: 10px;
+  width: 34px;
+  height: 34px;
+  background: rgba(13,13,15,.7);
+  backdrop-filter: blur(6px);
+  border-radius: 999px;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--text-muted);
+  transition: color var(--transition), background var(--transition);
+  opacity: 0;
+}
+
+.product-card:hover .product-card__wishlist,
+.product-card__wishlist:focus-visible {
+  opacity: 1;
+}
+
+.product-card__wishlist:hover,
+.product-card__wishlist[aria-pressed="true"] {
+  color: var(--deal-red);
+  background: rgba(13,13,15,.9);
+}
+
+.product-card__body {
+  padding: 16px;
+}
+
+.product-card__category {
+  font-size: .72rem;
+  font-weight: 600;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  color: var(--text-muted);
+  margin-bottom: 6px;
+}
+
+.product-card__name {
+  font-size: .95rem;
+  font-weight: 700;
+  line-height: 1.3;
+  margin-bottom: 8px;
+  color: var(--text-primary);
+}
+
+.product-card__rating {
+  display: flex;
+  align-items: center;
+  gap: 6px;
+  margin-bottom: 12px;
+}
+
+.product-card__stars {
+  display: flex;
+  gap: 2px;
+  color: var(--accent);
+}
+
+.product-card__stars svg { width: 12px; height: 12px; }
+
+.product-card__reviews {
+  font-size: .75rem;
+  color: var(--text-muted);
+}
+
+.product-card__footer {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 8px;
+}
+
+.product-card__price {
+  display: flex;
+  align-items: baseline;
+  gap: 8px;
+}
+
+.product-card__price-current {
+  font-size: 1.15rem;
+  font-weight: 800;
+  color: var(--text-primary);
+}
+
+.product-card__price-original {
+  font-size: .82rem;
+  color: var(--text-muted);
+  text-decoration: line-through;
+}
+
+.product-card__add {
+  width: 36px;
+  height: 36px;
+  background: var(--accent);
+  color: #0d0d0f;
+  border-radius: var(--radius-sm);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 1.2rem;
+  font-weight: 700;
+  flex-shrink: 0;
+  transition: background var(--transition), transform var(--transition);
+}
+
+.product-card__add:hover {
+  background: var(--accent-dim);
+  transform: scale(1.08);
+}
+
+.product-card__add[aria-pressed="true"] {
+  background: #2a6a2a;
+  color: #7affa0;
+}
+
+/* ── Deals Section ────────────────────────────────────────── */
+.deals { background: var(--bg-surface); }
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 20px;
+}
+
+.deal-card {
+  background: var(--bg-raised);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  padding: 28px;
+  display: flex;
+  gap: 24px;
+  align-items: center;
+  transition: transform var(--transition), box-shadow var(--transition);
+  overflow: hidden;
+  position: relative;
+}
+
+.deal-card::before {
+  content: '';
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(ellipse at 80% 50%, rgba(232,201,109,.06) 0%, transparent 60%);
+  pointer-events: none;
+}
+
+.deal-card:hover {
+  transform: translateY(-2px);
+  box-shadow: var(--shadow-hover);
+}
+
+.deal-card--featured {
+  grid-column: 1 / -1;
+  background: linear-gradient(135deg, var(--deal-bg) 0%, #1a1a2a 100%);
+  border-color: #4a2020;
+}
+
+.deal-card--featured::before {
+  background: radial-gradient(ellipse at 70% 50%, rgba(232,93,93,.08) 0%, transparent 60%);
+}
+
+.deal-card__emoji {
+  font-size: 4rem;
+  line-height: 1;
+  flex-shrink: 0;
+}
+
+.deal-card--featured .deal-card__emoji { font-size: 5rem; }
+
+.deal-card__content { flex: 1; min-width: 0; }
+
+.deal-card__tag {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  background: var(--deal-bg);
+  color: var(--deal-red);
+  font-size: .72rem;
+  font-weight: 700;
+  letter-spacing: .07em;
+  text-transform: uppercase;
+  padding: 4px 10px;
+  border-radius: 999px;
+  margin-bottom: 10px;
+  border: 1px solid #4a2020;
+}
+
+.deal-card--featured .deal-card__tag {
+  animation: pulse-bg 2.5s ease-in-out infinite;
+}
+
+@keyframes pulse-bg {
+  0%, 100% { background: var(--deal-bg); }
+  50% { background: #3a1c1c; }
+}
+
+.deal-card__name {
+  font-size: 1.15rem;
+  font-weight: 800;
+  margin-bottom: 8px;
+  line-height: 1.25;
+}
+
+.deal-card--featured .deal-card__name { font-size: 1.5rem; }
+
+.deal-card__desc {
+  font-size: .84rem;
+  color: var(--text-secondary);
+  margin-bottom: 16px;
+  line-height: 1.5;
+}
+
+.deal-card__price-row {
+  display: flex;
+  align-items: center;
+  gap: 12px;
+  margin-bottom: 16px;
+  flex-wrap: wrap;
+}
+
+.deal-card__price-current {
+  font-size: 1.5rem;
+  font-weight: 900;
+  letter-spacing: -.03em;
+}
+
+.deal-card--featured .deal-card__price-current { font-size: 2rem; }
+
+.deal-card__price-original {
+  font-size: .9rem;
+  color: var(--text-muted);
+  text-decoration: line-through;
+}
+
+.deal-card__savings {
+  background: var(--deal-bg);
+  color: var(--deal-red);
+  border: 1px solid var(--deal-red-dim);
+  font-size: .78rem;
+  font-weight: 700;
+  padding: 2px 8px;
+  border-radius: var(--radius-sm);
+}
+
+.deal-card__timer {
+  display: flex;
+  align-items: center;
+  gap: 6px;
+  font-size: .78rem;
+  color: var(--text-muted);
+  margin-bottom: 14px;
+}
+
+.deal-card__timer-display {
+  display: flex;
+  gap: 4px;
+}
+
+.timer-unit {
+  background: var(--bg-overlay);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-sm);
+  padding: 2px 6px;
+  font-weight: 700;
+  color: var(--text-primary);
+  font-variant-numeric: tabular-nums;
+  min-width: 28px;
+  text-align: center;
+}
+
+.deal-card__actions {
+  display: flex;
+  gap: 10px;
+  flex-wrap: wrap;
+}
+
+.btn--deal {
+  background: var(--deal-red);
+  color: #fff;
+  padding: 10px 20px;
+}
+
+.btn--deal:hover {
+  background: var(--deal-red-dim);
+  transform: translateY(-1px);
