*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-base:       #0d0d0f;
  --bg-surface:    #16161a;
  --bg-raised:     #1e1e24;
  --bg-overlay:    #26262e;
  --border:        #2e2e38;
  --accent:        #e8c96d;
  --accent-dim:    #c4a44a;
  --accent-muted:  #3a3018;
  --text-primary:  #f0eff4;
  --text-secondary:#a09fb5;
  --text-muted:    #64637a;
  --deal-red:      #e85d5d;
  --deal-red-dim:  #b84545;
  --deal-bg:       #2a1515;
  --radius-sm:     6px;
  --radius-md:     12px;
  --radius-lg:     20px;
  --shadow-card:   0 4px 24px rgba(0,0,0,.5);
  --shadow-hover:  0 8px 40px rgba(0,0,0,.7);
  --font-sans:     'Inter', system-ui, -apple-system, sans-serif;
  --font-serif:    'Georgia', 'Times New Roman', serif;
  --transition:    .18s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-base);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

img { display: block; max-width: 100%; }

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ── Skip Link ────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 8px;
  background: var(--accent);
  color: #0d0d0f;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  z-index: 9999;
  transition: top .15s;
}
.skip-link:focus { top: 8px; }

/* ── Focus Ring ───────────────────────────────────────────── */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ── Layout Utility ───────────────────────────────────────── */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Header / Nav ─────────────────────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,.9);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}

.nav {
  display: flex;
  align-items: center;
  gap: 24px;
  height: 64px;
}

.nav__logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -.5px;
  color: var(--text-primary);
  flex-shrink: 0;
}

.nav__logo-icon {
  width: 32px;
  height: 32px;
  background: var(--accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #0d0d0f;
  font-weight: 900;
  font-size: .95rem;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
  margin-left: 8px;
}

.nav__links a {
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}

.nav__links a:hover,
.nav__links a[aria-current="page"] {
  color: var(--text-primary);
  background: var(--bg-raised);
}

.nav__spacer { flex: 1; }

.nav__search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 7px 16px;
  width: 220px;
  transition: border-color var(--transition), width var(--transition);
}

.nav__search:focus-within {
  border-color: var(--accent);
  width: 280px;
}

.nav__search svg { color: var(--text-muted); flex-shrink: 0; }

